method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0 // The list must have at least one coefficient
    ensures |result| == |xs| - 1 // The result will have one less coefficient than the input
    ensures result == [i * xs[i + 1] | i := 0..|xs| - 2] // Each element of the result is derived from the polynomial
{
    var n := |xs|; 
    var coeffs := new int[n - 1];
    var i := 0;

    while i < n - 1
        invariant 0 <= i <= n - 1
        invariant coeffs.Length == n - 1
    {
        coeffs[i] := xs[i + 1] * (i + 1);
        i := i + 1;
    }

    result := coeffs;
}
